/* workponents — the design contract.
 * Every <wb-*> element styles ONLY from these custom properties. CSS custom
 * properties inherit through the shadow boundary, so setting --work-* on :root (or
 * any ancestor / [data-work-theme] scope) themes every element beneath it. One set
 * governs all domains AND the workbook artifacts. Authors theme by overriding
 * tokens — never by reaching into a component. Per-workspace brands = a scope
 * with its own token overrides (the demo brands are this pattern). */

:root,
[data-work-theme="light"] {
  /* surfaces */
  --work-bg: #f7f6f1;
  --work-surface: #ffffff;
  --work-surface-soft: #efede6;
  --work-border: rgba(18, 19, 22, 0.13);
  --work-border-strong: rgba(18, 19, 22, 0.28);
  /* foreground */
  --work-fg: #121316;
  --work-fg-muted: rgba(18, 19, 22, 0.6);
  --work-fg-subtle: rgba(18, 19, 22, 0.38);
  /* brand + state */
  --work-brand: #13d943;
  --work-brand-soft: rgba(19, 217, 67, 0.13);
  --work-brand-ink: #0a2413;
  --work-on-brand: #07210f;
  --work-ring: rgba(19, 217, 67, 0.5);
  --work-ok: #0fae38;
  --work-warn: #b8861b;
  --work-err: #c92f2f;
  /* text on a solid state fill, + soft tints of each state */
  --work-on-state: #ffffff;
  --work-on-warn: #1c1304;
  --work-ok-soft: rgba(15, 174, 56, 0.14);
  --work-warn-soft: rgba(184, 134, 27, 0.14);
  --work-err-soft: rgba(201, 47, 47, 0.14);
  /* state glow rings + chip fills (stronger than the -soft tints) */
  --work-warn-glow: rgba(184, 134, 27, 0.18);
  --work-warn-fill: rgba(184, 134, 27, 0.16);
  --work-err-glow: rgba(201, 47, 47, 0.28);
  --work-err-faint: rgba(201, 47, 47, 0.10);
  /* diff add/del backgrounds (theme-agnostic — readable on any surface) */
  --work-diff-add: rgba(16, 174, 56, 0.13);
  --work-diff-del: rgba(201, 47, 47, 0.13);
  --work-diff-add-strong: rgba(16, 174, 56, 0.16);
  --work-diff-del-strong: rgba(201, 47, 47, 0.16);
  /* scrim + ink on scrim (media letterbox, modal backdrop, ink on a fill) */
  --work-scrim: #000000;
  --work-scrim-soft: rgba(8, 10, 14, 0.5);
  --work-on-scrim: #ffffff;
  /* pastel chips (per-tone accents) */
  --work-chip-blue: #aecbf2;
  --work-chip-green: #b6e2bd;
  --work-chip-peach: #f3cfae;
  --work-chip-lavender: #d4c9f0;

  /* shape */
  --work-radius: 12px;
  --work-radius-sm: 8px;
  --work-radius-lg: 18px;
  --work-radius-pill: 999px;
  /* spacing scale */
  --work-space-1: 4px;
  --work-space-2: 8px;
  --work-space-3: 12px;
  --work-space-4: 16px;
  --work-space-5: 24px;
  /* type */
  --work-font: "Geist", system-ui, -apple-system, sans-serif;
  --work-font-mono: "Geist Mono", "JetBrains Mono", ui-monospace, monospace;
  --work-font-display: "Franie", "Geist", sans-serif;
  --work-text-sm: 12.5px;
  --work-text: 14px;
  --work-text-lg: 16px;
  --work-text-xs: 11px;
  /* data-viz (Plot tier): KPI display scale + fine radius/space rungs */
  --work-text-metric-sm: 22px;
  --work-text-metric: 30px;
  --work-text-metric-lg: 42px;
  --work-radius-xs: 3px;
  --work-radius-4px: 4px;
  --work-radius-7px: 7px;
  --work-space-px: 1px;
  /* fine spacing rungs (tight chrome: chips, pills, badges, dense rows) */
  --work-space-2px: 2px;
  --work-space-3px: 3px;
  --work-space-5px: 5px;
  --work-space-6px: 6px;
  --work-space-7px: 7px;
  --work-space-9px: 9px;
  /* fine + glyph type rungs (mono labels, icons, large display glyphs) */
  --work-text-3xs: 9px;
  --work-text-2xs: 10px;
  --work-text-label: 10.5px;
  --work-text-md: 13px;
  --work-text-icon: 15px;
  --work-glyph-sm: 24px;
  --work-glyph: 26px;
  --work-glyph-lg: 38px;
  /* depth + motion */
  --work-shadow: 0 1px 2px rgba(18, 19, 22, 0.06), 0 8px 24px rgba(18, 19, 22, 0.08);
  --work-shadow-sm: 0 1px 2px rgba(18, 19, 22, 0.08);
  --work-ease: cubic-bezier(0.2, 0.7, 0.2, 1);
  --work-dur: 0.14s;
}

[data-work-theme="dark"] {
  --work-bg: #0a0d13;
  --work-surface: #10151f;
  --work-surface-soft: #161c27;
  --work-border: #23262c;
  --work-border-strong: #353a44;
  --work-fg: #e9edf4;
  --work-fg-muted: #9aa0a6;
  --work-fg-subtle: #6b727c;
  /* live-green primary on dark (per brand canon) */
  --work-brand: #3fe081;
  --work-brand-soft: rgba(63, 224, 129, 0.14);
  --work-brand-ink: #d7ffe6;
  --work-on-brand: #07210f;
  --work-ring: rgba(63, 224, 129, 0.5);
  --work-ok: #4f9d6b;
  --work-warn: #f5a524;
  --work-err: #ef5350;
  --work-on-state: #07210f;
  --work-on-warn: #1c1304;
  --work-ok-soft: rgba(79, 157, 107, 0.18);
  --work-warn-soft: rgba(245, 165, 36, 0.18);
  --work-err-soft: rgba(239, 83, 80, 0.18);
  --work-warn-glow: rgba(245, 165, 36, 0.18);
  --work-warn-fill: rgba(245, 165, 36, 0.16);
  --work-err-glow: rgba(239, 83, 80, 0.28);
  --work-err-faint: rgba(239, 83, 80, 0.10);
  --work-shadow: 0 1px 2px rgba(0, 0, 0, 0.4), 0 10px 30px rgba(0, 0, 0, 0.45);
  --work-shadow-sm: 0 1px 2px rgba(0, 0, 0, 0.4);
}

/* A preset shows the per-workspace-brand pattern: a scope with its own overrides
 * (here: Signal — dark institutional terminal, sharp corners, mono). */
[data-work-theme="signal"] {
  --work-bg: #0a0d13; --work-surface: #10151f; --work-surface-soft: #161c27;
  --work-border: #1c232f; --work-border-strong: #2a3340;
  --work-fg: #e9edf4; --work-fg-muted: #8893a6; --work-fg-subtle: #5b6573;
  --work-brand: #3da9fc; --work-brand-soft: rgba(61,169,252,0.14); --work-on-brand: #04121f;
  --work-ring: rgba(61,169,252,0.5);
  --work-radius: 2px; --work-radius-sm: 2px; --work-radius-lg: 3px; --work-radius-pill: 3px; --work-radius-xs: 1px;
  --work-radius-4px: 2px; --work-radius-7px: 3px;
  --work-font: "Space Grotesk", system-ui, sans-serif;
  --work-font-mono: "IBM Plex Mono", ui-monospace, monospace;
  --work-font-display: "Space Grotesk", sans-serif;
}

// workponents · theme registry — the browser/artifact-side theme runtime.
//
// The desktop Rust layer (store.rs `Theme{id,name,light_tokens,dark_tokens}`)
// + themes.svelte.ts are the AUTHORING/PERSISTENCE side and speak `--color-*`.
// This is the COMPLEMENT they were missing: a zero-dependency runtime that any
// workbook artifact (a static .html with no Tauri, no desktop) carries with it,
// so a workbook can register + apply a `--work-*` theme on hydrate.
//
// A theme is data, not CSS:
//
//   {
//     id: "signal",
//     name: "Signal",
//     extends: "dark",                      // base preset to inherit ("light"|"dark")
//     tokens: { light: { "work-bg": "#…", … }, dark: { … } },
//     fonts:  { sans: "…", mono: "…" },     // optional; map to --work-font / --work-font-mono
//   }
//
// Token KEYS are bare names ("work-bg"), NOT `--work-bg` — applyTheme writes the
// `--` prefix, exactly like themes.svelte.ts writes `--${k}`. This keeps the
// registry data shape identical to the Rust registry's token maps.
//
// apply/revert mirrors themes.svelte.ts `applyActive()`: write each token inline
// on the scope element (inline styles beat tokens.css's `:root` rule and any
// `data-work-theme` rule), track the applied set, and remove stale props from a
// previous theme before applying the new one so themes never bleed into each
// other. One scope element is themed at a time; pass a different scope to theme a
// subtree (a per-artifact brand region).

/** id → theme record */
const _registry = new Map();
/** scope element → { id, mode, applied:Set<string> } */
const _active = new WeakMap();
/** the last scope applyTheme touched, so activeTheme()/revert default to it */
let _lastScope = null;

/** The font tokens a theme's `fonts` map drives, by font key. */
const FONT_TOKENS = { sans: "work-font", mono: "work-font-mono", display: "work-font-display" };

/**
 * Register (or replace) a theme. Returns the stored record.
 * @param {object} theme { id, name, extends?, tokens:{light,dark}, fonts? }
 */
export function registerTheme(theme) {
  if (!theme || typeof theme.id !== "string" || !theme.id) {
    throw new Error("registerTheme: theme.id (string) is required");
  }
  const rec = {
    id: theme.id,
    name: theme.name || theme.id,
    extends: theme.extends === "dark" ? "dark" : "light",
    tokens: {
      light: { ...(theme.tokens && theme.tokens.light) },
      dark: { ...(theme.tokens && theme.tokens.dark) },
    },
    fonts: { ...(theme.fonts || {}) },
  };
  _registry.set(rec.id, rec);
  return rec;
}

/** All registered theme records (in registration order). */
export function listThemes() {
  return [..._registry.values()];
}

/** A single registered theme record, or null. */
export function getTheme(id) {
  return _registry.get(id) || null;
}

/**
 * Resolve the flat token map a theme applies for a given mode.
 * Merges fonts into the token map (fonts.sans → work-font, etc.).
 * @returns {Record<string,string>} bare-name token map ("work-bg": "#…")
 */
export function resolveTokens(id, mode = "light") {
  const t = _registry.get(id);
  if (!t) return {};
  const base = mode === "dark" ? t.tokens.dark : t.tokens.light;
  const out = { ...base };
  for (const [fk, tok] of Object.entries(FONT_TOKENS)) {
    if (t.fonts && t.fonts[fk]) out[tok] = t.fonts[fk];
  }
  return out;
}

function pickScope(scope) {
  if (scope) return scope;
  if (typeof document !== "undefined") return document.documentElement;
  return null;
}

/**
 * Apply a registered theme to a scope element by writing `--work-*` inline.
 * Mirrors themes.svelte.ts applyActive(): removes stale props from whatever
 * theme was last applied to this scope, then writes the new set. Also reflects
 * the chosen mode onto `data-work-theme` so the tokens.css preset rule and the
 * inline override agree.
 *
 * @param {string} id registered theme id
 * @param {object} [opts]
 * @param {"light"|"dark"} [opts.mode="light"]
 * @param {Element} [opts.scope] element to theme (default: documentElement)
 * @returns {{id:string, mode:string, tokens:Record<string,string>}}
 */
export function applyTheme(id, { mode = "light", scope } = {}) {
  const el = pickScope(scope);
  if (!el) throw new Error("applyTheme: no scope element (no document)");
  const t = _registry.get(id);
  if (!t) throw new Error(`applyTheme: unknown theme "${id}"`);

  const tokens = resolveTokens(id, mode);
  const nextKeys = new Set(Object.keys(tokens));

  const prev = _active.get(el);
  if (prev) {
    for (const k of prev.applied) {
      if (!nextKeys.has(k)) el.style.removeProperty(`--${k}`);
    }
  }
  for (const [k, v] of Object.entries(tokens)) {
    el.style.setProperty(`--${k}`, v);
  }
  // Keep the preset selector in sync — extend the base preset, label the scope.
  el.setAttribute("data-work-theme", mode === "dark" ? "dark" : "light");

  _active.set(el, { id, mode, applied: nextKeys });
  _lastScope = el;
  return { id, mode, tokens };
}

/**
 * Revert a scope to its un-themed state — drops every inline `--work-*` this
 * registry applied, so tokens.css's defaults take over again.
 */
export function revertTheme(scope) {
  const el = pickScope(scope);
  if (!el) return;
  const prev = _active.get(el);
  if (prev) {
    for (const k of prev.applied) el.style.removeProperty(`--${k}`);
    _active.delete(el);
  }
  el.removeAttribute("data-work-theme");
  if (_lastScope === el) _lastScope = null;
}

/**
 * The theme currently applied to a scope (default: the last scope applyTheme
 * touched, else documentElement). Returns { id, mode } or null.
 */
export function activeTheme(scope) {
  const el = pickScope(scope || _lastScope);
  if (!el) return null;
  const a = _active.get(el);
  return a ? { id: a.id, mode: a.mode } : null;
}

// ── Seed: the 3 current presets become DATA, not just CSS. ──────────────────
// These mirror tokens.css 1:1 (light :root, dark, signal) so the registry IS the
// source of truth; tokens.css remains the static default for no-JS artifacts.
// Built-ins are registered on import so a bare `import "./registry.js"` already
// has light/dark/signal available to applyTheme.

registerTheme({
  id: "light",
  name: "Paper (light)",
  extends: "light",
  tokens: {
    light: {
      "work-bg": "#f7f6f1", "work-surface": "#ffffff", "work-surface-soft": "#efede6",
      "work-border": "rgba(18, 19, 22, 0.13)", "work-border-strong": "rgba(18, 19, 22, 0.28)",
      "work-fg": "#121316", "work-fg-muted": "rgba(18, 19, 22, 0.6)", "work-fg-subtle": "rgba(18, 19, 22, 0.38)",
      "work-brand": "#13d943", "work-brand-soft": "rgba(19, 217, 67, 0.13)", "work-brand-ink": "#0a2413",
      "work-on-brand": "#07210f", "work-ring": "rgba(19, 217, 67, 0.5)",
      "work-ok": "#0fae38", "work-warn": "#b8861b", "work-err": "#c92f2f",
      "work-on-state": "#ffffff", "work-on-warn": "#1c1304",
      "work-ok-soft": "rgba(15, 174, 56, 0.14)", "work-warn-soft": "rgba(184, 134, 27, 0.14)", "work-err-soft": "rgba(201, 47, 47, 0.14)",
      "work-warn-glow": "rgba(184, 134, 27, 0.18)", "work-warn-fill": "rgba(184, 134, 27, 0.16)",
      "work-err-glow": "rgba(201, 47, 47, 0.28)", "work-err-faint": "rgba(201, 47, 47, 0.10)",
      "work-diff-add": "rgba(16, 174, 56, 0.13)", "work-diff-del": "rgba(201, 47, 47, 0.13)",
      "work-diff-add-strong": "rgba(16, 174, 56, 0.16)", "work-diff-del-strong": "rgba(201, 47, 47, 0.16)",
      "work-scrim": "#000000", "work-scrim-soft": "rgba(8, 10, 14, 0.5)", "work-on-scrim": "#ffffff",
      "work-chip-blue": "#aecbf2", "work-chip-green": "#b6e2bd", "work-chip-peach": "#f3cfae", "work-chip-lavender": "#d4c9f0",
    },
    dark: {},
  },
  fonts: { sans: '"Geist", system-ui, -apple-system, sans-serif', mono: '"Geist Mono", "JetBrains Mono", ui-monospace, monospace', display: '"Franie", "Geist", sans-serif' },
});

registerTheme({
  id: "dark",
  name: "Ink (dark)",
  extends: "dark",
  tokens: {
    light: {},
    dark: {
      "work-bg": "#0a0d13", "work-surface": "#10151f", "work-surface-soft": "#161c27",
      "work-border": "#23262c", "work-border-strong": "#353a44",
      "work-fg": "#e9edf4", "work-fg-muted": "#9aa0a6", "work-fg-subtle": "#6b727c",
      "work-brand": "#3fe081", "work-brand-soft": "rgba(63, 224, 129, 0.14)", "work-brand-ink": "#d7ffe6",
      "work-on-brand": "#07210f", "work-ring": "rgba(63, 224, 129, 0.5)",
      "work-ok": "#4f9d6b", "work-warn": "#f5a524", "work-err": "#ef5350",
      "work-on-state": "#07210f", "work-on-warn": "#1c1304",
      "work-ok-soft": "rgba(79, 157, 107, 0.18)", "work-warn-soft": "rgba(245, 165, 36, 0.18)", "work-err-soft": "rgba(239, 83, 80, 0.18)",
      "work-warn-glow": "rgba(245, 165, 36, 0.18)", "work-warn-fill": "rgba(245, 165, 36, 0.16)",
      "work-err-glow": "rgba(239, 83, 80, 0.28)", "work-err-faint": "rgba(239, 83, 80, 0.10)",
      "work-diff-add": "rgba(16, 174, 56, 0.13)", "work-diff-del": "rgba(201, 47, 47, 0.13)",
      "work-diff-add-strong": "rgba(16, 174, 56, 0.16)", "work-diff-del-strong": "rgba(201, 47, 47, 0.16)",
      "work-scrim": "#000000", "work-scrim-soft": "rgba(8, 10, 14, 0.5)", "work-on-scrim": "#ffffff",
    },
  },
});

registerTheme({
  id: "signal",
  name: "Signal",
  extends: "dark",
  tokens: {
    light: {},
    dark: {
      "work-bg": "#0a0d13", "work-surface": "#10151f", "work-surface-soft": "#161c27",
      "work-border": "#1c232f", "work-border-strong": "#2a3340",
      "work-fg": "#e9edf4", "work-fg-muted": "#8893a6", "work-fg-subtle": "#5b6573",
      "work-brand": "#3da9fc", "work-brand-soft": "rgba(61,169,252,0.14)", "work-on-brand": "#04121f",
      "work-ring": "rgba(61,169,252,0.5)",
      "work-radius": "2px", "work-radius-sm": "2px", "work-radius-lg": "3px", "work-radius-pill": "3px",
      "work-radius-xs": "1px", "work-radius-4px": "2px", "work-radius-7px": "3px",
    },
  },
  fonts: { sans: '"Space Grotesk", system-ui, sans-serif', mono: '"IBM Plex Mono", ui-monospace, monospace', display: '"Space Grotesk", sans-serif' },
});

/* workponents · theme bridge — derive `--work-*` from the desktop `--color-*`.
 *
 * ONE DIRECTION ONLY: the desktop app's existing `--color-*` registry (app.css
 * @theme + themes.svelte.ts runtime overrides) is the source; `--work-*` is the
 * alias. Include this stylesheet in the desktop (or any host that already speaks
 * `--color-*`) and every `<work-*>` element inherits the host theme through the
 * shadow boundary with ZERO desktop churn — no token rename, no per-element edit.
 *
 * Why a separate file (not folded into tokens.css): tokens.css is the canonical
 * standalone contract for no-host artifacts (a bare workbook .html themes itself
 * from tokens.css + registry.js). bridge.css is opt-in glue you load ONLY inside
 * a `--color-*` host. The two never load together.
 *
 * `--color-*` names are read from desktop/src/app.css. Tokens the host registry
 * has no equivalent for (on-brand, radius/space scale, type scale, display font)
 * fall back to the same literals tokens.css uses — so a `work-*` element under
 * the bridge is fully themed, never half-tokened. Where a `--color-*` exists it
 * wins via var() with the literal as the fallback arm. */

:root {
  /* surfaces — direct host equivalents */
  --work-bg: var(--color-page, #f7f6f1);
  --work-surface: var(--color-surface, #ffffff);
  --work-surface-soft: var(--color-surface-soft, #efede6);
  --work-border: var(--color-border, rgba(18, 19, 22, 0.13));
  --work-border-strong: var(--color-border-strong, rgba(18, 19, 22, 0.28));

  /* foreground — direct host equivalents */
  --work-fg: var(--color-fg, #121316);
  --work-fg-muted: var(--color-fg-muted, rgba(18, 19, 22, 0.6));
  --work-fg-subtle: var(--color-fg-subtle, rgba(18, 19, 22, 0.38));

  /* brand + state — host has brand/brand-soft/brand-ink/ring/ok/warn/err.
   * NOTE the host's --color-accent is the INK button fill (paper canon), NOT
   * the bloom brand, so --work-brand maps to --color-brand (the bloom), not
   * accent. --work-on-brand has no host token (host pairs brand with ink text
   * elsewhere) → literal fallback. */
  --work-brand: var(--color-brand, #13d943);
  --work-brand-soft: var(--color-brand-soft, rgba(19, 217, 67, 0.13));
  --work-brand-ink: var(--color-brand-ink, #0a2413);
  --work-on-brand: #07210f;
  --work-ring: var(--color-ring, rgba(19, 217, 67, 0.5));
  --work-ok: var(--color-ok, #0fae38);
  --work-warn: var(--color-warn, #b8861b);
  --work-err: var(--color-err, #c92f2f);
  /* state ink + tints — no host equivalent; tokens.css literals. */
  --work-on-state: #ffffff;
  --work-on-warn: #1c1304;
  --work-ok-soft: rgba(15, 174, 56, 0.14);
  --work-warn-soft: rgba(184, 134, 27, 0.14);
  --work-err-soft: rgba(201, 47, 47, 0.14);
  /* state glows + fills, diff backgrounds, scrim — no host equivalent. */
  --work-warn-glow: rgba(184, 134, 27, 0.18);
  --work-warn-fill: rgba(184, 134, 27, 0.16);
  --work-err-glow: rgba(201, 47, 47, 0.28);
  --work-err-faint: rgba(201, 47, 47, 0.10);
  --work-diff-add: rgba(16, 174, 56, 0.13);
  --work-diff-del: rgba(201, 47, 47, 0.13);
  --work-diff-add-strong: rgba(16, 174, 56, 0.16);
  --work-diff-del-strong: rgba(201, 47, 47, 0.16);
  --work-scrim: #000000;
  --work-scrim-soft: rgba(8, 10, 14, 0.5);
  --work-on-scrim: #ffffff;

  /* pastel chips — direct host equivalents */
  --work-chip-blue: var(--color-chip-blue, #aecbf2);
  --work-chip-green: var(--color-chip-green, #b6e2bd);
  --work-chip-peach: var(--color-chip-peach, #f3cfae);
  --work-chip-lavender: var(--color-chip-lavender, #d4c9f0);

  /* shape — host has --radius-lg (8px) only; map --work-radius* around it. */
  --work-radius: var(--radius-lg, 12px);
  --work-radius-sm: 8px;
  --work-radius-lg: 18px;
  --work-radius-pill: 999px;
  --work-radius-xs: 3px;
  --work-radius-4px: 4px;
  --work-radius-7px: 7px;

  /* spacing — no host scale; tokens.css literals. */
  --work-space-px: 1px;
  --work-space-2px: 2px;
  --work-space-3px: 3px;
  --work-space-5px: 5px;
  --work-space-6px: 6px;
  --work-space-7px: 7px;
  --work-space-9px: 9px;
  --work-space-1: 4px;
  --work-space-2: 8px;
  --work-space-3: 12px;
  --work-space-4: 16px;
  --work-space-5: 24px;

  /* type — host has --font-sans / --font-mono; no display or text scale. */
  --work-font: var(--font-sans, "Geist", system-ui, -apple-system, sans-serif);
  --work-font-mono: var(--font-mono, "JetBrains Mono", ui-monospace, monospace);
  --work-font-display: var(--font-sans, "Franie", "Geist", sans-serif);
  --work-text-xs: 11px;
  --work-text-sm: 12.5px;
  --work-text: 14px;
  --work-text-lg: 16px;
  --work-text-3xs: 9px;
  --work-text-2xs: 10px;
  --work-text-label: 10.5px;
  --work-text-md: 13px;
  --work-text-icon: 15px;
  --work-glyph-sm: 24px;
  --work-glyph: 26px;
  --work-glyph-lg: 38px;

  /* depth + motion — host has --shadow-pop; no -sm/ease/dur. */
  --work-shadow: var(--shadow-pop, 0 1px 2px rgba(18, 19, 22, 0.06), 0 8px 24px rgba(18, 19, 22, 0.08));
  --work-shadow-sm: 0 1px 2px rgba(18, 19, 22, 0.08);
  --work-ease: cubic-bezier(0.2, 0.7, 0.2, 1);
  --work-dur: 0.14s;
}

